import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';
import { OrderRepository } from '../src/repositories/order-repository.js';

const call = (fn, ...args) => new Promise((resolve, reject) =>
  fn(...args, (err, value) => (err ? reject(err) : resolve(value))));

test('listOrdersForUser returns only that user orders', (t, done) => {
  listOrdersForUser(1, (err, orders) => {
    assert.equal(err, null);
    assert.equal(orders.length, 2);
    assert.ok(orders.every((o) => o.user_id === 1));
    done();
  });
});

test('listOrdersForUser returns the same rows as OrderRepository.findByUser', async () => {
  const expected = await new OrderRepository().findByUser(1);
  assert.deepEqual(await call(listOrdersForUser, 1), expected);
});

test('listOrdersForUser returns an empty list for an unknown user', async () => {
  assert.deepEqual(await call(listOrdersForUser, 999), []);
});

test('totalPaidCents counts only paid orders', (t, done) => {
  totalPaidCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 4200 + 9900 + 500);
    done();
  });
});

test('totalPaidCents sums the rows from OrderRepository.findPaid', async () => {
  const paid = await new OrderRepository().findPaid();
  const expected = paid.reduce((sum, o) => sum + o.total_cents, 0);
  assert.equal(await call(totalPaidCents), expected);
});

